package com.ospreydcs.dp.client.result;

public class SaveConfigurationActivationApiResult extends ApiResultBase {

    // instance variables

    /*
     * Identifier of the saved activation record.  This is the clientActivationId supplied in the
     * request, or, when the request omitted one, the identifier generated by the server.  In the
     * latter case this is the caller's only handle on the new record.
     */
    public final String clientActivationId;

    public SaveConfigurationActivationApiResult(boolean isError, String errorMessage) {
        super(isError, errorMessage);
        this.clientActivationId = null;
    }

    public SaveConfigurationActivationApiResult(boolean isError, String errorMessage, ApiResultStatus apiResultStatus) {
        super(isError, errorMessage, apiResultStatus);
        this.clientActivationId = null;
    }

    public SaveConfigurationActivationApiResult(String clientActivationId) {
        super(false, "");
        this.clientActivationId = clientActivationId;
    }

}
